  /**
   * @method
   * @name hashkey#fetchOpenOrders
   * @description fetch all unfilled currently open orders
   * @see
   * https://hashkeyglobal-apidoc.readme.io/reference/get-current-open-orders
   * @see
   * https://hashkeyglobal-apidoc.readme.io/reference/get-sub-account-open-orders
   * @see https://hashkeyglobal-apidoc.readme.io/reference/sub
   * @see
   * https://hashkeyglobal-apidoc.readme.io/reference/query-open-futures-orders
   * @param {string} [symbol] unified market symbol of the market orders were
   * made in - is mandatory for swap markets
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve -
   * default 500, maximum 1000
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.type] 'spot' or 'swap' - the type of the market to
   * fetch entries for (default 'spot')
   * @param {string} [params.orderId] *spot markets only* the id of the order to
   * fetch
   * @param {string} [params.side] *spot markets only* 'buy' or 'sell' - the
   * side of the orders to fetch
   * @param {string} [params.fromOrderId] *swap markets only* the id of the
   * order to start from
   * @param {bool} [params.trigger] *swap markets only* true for fetching
   * trigger orders (default false)
   * @param {bool} [params.stop] *swap markets only* an alternative for trigger
   * param
   * @param {string} [params.accountId] account id to fetch the orders from
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  std::shared_future<std::any>
  fetchOpenOrders(std::any symbol = std::any{}, std::any since = std::any{},
                  std::any limit = std::any{},
                  std::any params = ccxt::dict{}) override {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 std::any methodName = std::string("fetchOpenOrders");
                 this->checkTypeParam(methodName, params);
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any market = std::any{};
                 if (isTrue(!isEqual(symbol, std::any{}))) {
                   market = this->market(symbol);
                 }
                 std::any marketType = std::string("spot");
                 std::any marketTypeparamsVariable =
                     this->handleMarketTypeAndParams(methodName, market, params,
                                                     marketType);
                 marketType = ::getValue(marketTypeparamsVariable, 0);
                 params = ::getValue(marketTypeparamsVariable, 1);
                 params = this->extend(
                     ccxt::dict{
                         {std::string("methodName"), methodName},
                     },
                     params);
                 if (isTrue(isEqual(marketType, std::string("spot")))) {
                   return awaitValue(
                       this->fetchOpenSpotOrders(symbol, since, limit, params));
                 } else if (isTrue(isEqual(marketType, std::string("swap")))) {
                   return awaitValue(
                       this->fetchOpenSwapOrders(symbol, since, limit, params));
                 } else {
                   throw NotSupported(toString(add(
                       add(add(add(add(this->id, std::string(" ")), methodName),
                               std::string("() is not supported for ")),
                           marketType),
                       std::string(" type of markets"))));
                 }
                 return std::any{};
               })
        .share();
  }

  /**
   * @method
   * @ignore
   * @name hashkey#fetchOpenSpotOrders
   * @description fetch all unfilled currently open orders for spot markets
   * @see
   * https://hashkeyglobal-apidoc.readme.io/reference/get-current-open-orders
   * @see https://hashkeyglobal-apidoc.readme.io/reference/sub
   * @param {string} [symbol] unified market symbol of the market orders were
   * made in
   * @param {int} [since] the earliest time in ms to fetch orders for
   * @param {int} [limit] the maximum number of order structures to retrieve -
   * default 500, maximum 1000
   * @param {object} [params] extra parameters specific to the exchange API
   * endpoint
   * @param {string} [params.orderId] the id of the order to fetch
   * @param {string} [params.side] 'buy' or 'sell' - the side of the orders to
   * fetch
   * @param {string} [params.accountId] account id to fetch the orders from
   * @returns {Order[]} a list of [order structures]{@link
   * https://docs.ccxt.com/?id=order-structure}
   */
  virtual std::shared_future<std::any>
  fetchOpenSpotOrders(std::any symbol = std::any{}, std::any since = std::any{},
                      std::any limit = std::any{},
                      std::any params = ccxt::dict{}) {
    return std::async(
               std::launch::deferred,
               [=]() mutable -> std::any {
                 if (isTrue(isEqual(this->markets, std::any{}))) {
                   awaitValue(this->loadMarkets());
                 }
                 std::any methodName = std::string("fetchOpenSpotOrders");
                 std::any methodNameparamsVariable = this->handleParamString(
                     params, std::string("methodName"), methodName);
                 methodName = ::getValue(methodNameparamsVariable, 0);
                 params = ::getValue(methodNameparamsVariable, 1);
                 std::any market = std::any{};
                 std::any request = ccxt::dict{};
                 std::any response = std::any{};
                 std::any accountId = std::any{};
                 std::any accountIdparamsVariable = this->handleOptionAndParams(
                     params, methodName, std::string("accountId"));
                 accountId = ::getValue(accountIdparamsVariable, 0);
                 params = ::getValue(accountIdparamsVariable, 1);
                 if (isTrue(!isEqual(accountId, std::any{}))) {
                   ::setValue(request, std::string("subAccountId"), accountId);
                   response =
                       awaitValue(this->privateGetApiV1SpotSubAccountOpenOrders(
                           this->extend(request, params)));
                 } else {
                   if (isTrue(!isEqual(symbol, std::any{}))) {
                     market = this->market(symbol);
                     ::setValue(request, std::string("symbol"),
                                ::getValue(market, std::string("id")));
                   }
                   if (isTrue(!isEqual(limit, std::any{}))) {
                     ::setValue(request, std::string("limit"), limit);
                   }
                   response = awaitValue(this->privateGetApiV1SpotOpenOrders(
                       this->extend(request, params)));
                 }
                 return this->parseOrders(response, market, since, limit);
               })
        .share();
  }

